handler.function:
console.log('\n' + '='.repeat(80));
console.log('📊 [QualityEvaluation] Quality evaluation started');
console.log('='.repeat(80));

const messages = state.messages;

// Extract research results from last user message
const lastMessage = messages[messages.length - 1];
let userContent = '';

if (lastMessage) {
  if (lastMessage.content) {
    userContent = lastMessage.content;
  } else if (lastMessage.parts && Array.isArray(lastMessage.parts)) {
    userContent = lastMessage.parts[0]?.text || lastMessage.parts[0]?.content || '';
  } else if (typeof lastMessage === 'string') {
    userContent = lastMessage;
  }
}

console.log('\n📨 Analyzing received message:');
console.log('  Content length:', userContent.length, 'chars');
console.log('  First 300 chars:', userContent.substring(0, 300));

// Parse new data structure sent from client
let originalRequest = '';
let researchResults = [];

try {
  console.log('\n🔍 Starting JSON parsing...');

  // Remove prefix text and extract JSON part
  const jsonMatch = userContent.match(/\{[\s\S]*\}/);

  if (jsonMatch) {
    console.log('  ✓ JSON part detected');

    let jsonStr = jsonMatch[0];

    // JSON5-like processing: properly escape control characters in string literals
    // As a more robust method, try JSON.parse first in try-catch, fallback if it fails
    let evaluationData;
    try {
      evaluationData = JSON.parse(jsonStr);
    } catch (parseError) {
      console.log('  ⚠️ Standard JSON.parse failed, attempting string correction');
      console.log('    Error:', parseError.message);

      // Escape control characters in string values (simplified version)
      // Convert newlines, tabs, carriage returns to \\n, \\t, \\r within double quotes
      // Note: This method is not perfect but covers common cases
      jsonStr = jsonStr.replace(/"([^"]*)"/g, (match, content) => {
        const escaped = content
          .replace(/\n/g, '\\n')
          .replace(/\r/g, '\\r')
          .replace(/\t/g, '\\t');
        return `"${escaped}"`;
      });

      evaluationData = JSON.parse(jsonStr);
    }
    console.log('  ✓ evaluationData parsed successfully');
    console.log('    - originalRequest:', evaluationData.originalRequest?.substring(0, 50));
    console.log('    - totalResults:', evaluationData.totalResults);

    originalRequest = evaluationData.originalRequest || '';

    // Use researchResults directly (already flattened on client side)
    if (evaluationData.researchResults && Array.isArray(evaluationData.researchResults)) {
      console.log('  ✓ researchResults array detected:', evaluationData.researchResults.length, 'items');
      researchResults = evaluationData.researchResults;
      console.log('  ✅ Using research results directly:', researchResults.length, 'items');
    }
  } else {
    // ★Phase 8: Support for natural language format
    console.log('  ✓ Natural language format detected');
    console.log('  Processing entire text as a single research result');

    // Extract user request (first line or after "以下の")
    const requestMatch = userContent.match(/^([^\n:：]+)[：:]/);
    if (requestMatch) {
      originalRequest = requestMatch[1].trim();
    } else {
      originalRequest = 'Quality evaluation of research results';
    }

    console.log('  Extracted user request:', originalRequest);

    // Treat entire text as a single research result
    researchResults = [{
      taskId: 1,
      objective: 'Comprehensive research report',
      findings: userContent,
      sources: [],
      format: 'natural_language'
    }];

    console.log('  ✅ Converted natural language text to research result');
  }
} catch (e) {
  console.error('\n❌ JSON parsing error:', e.message);
  console.error('  Stack:', e.stack);
  console.log('  Fallback: treating entire content as text');

  // ★Phase 8: Improved fallback processing
  originalRequest = 'Text parsing error';
  researchResults = [{
    taskId: 1,
    objective: 'Error recovery',
    findings: userContent,
    sources: []
  }];
}

console.log('\n📋 Parsing result summary:');
console.log('  Original user request:', originalRequest.substring(0, 100) + '...');
console.log('  Number of research results:', researchResults.length);

// Error handling when research results are not found
if (researchResults.length === 0) {
  console.warn('\n⚠️  Warning: No research results found');
  console.log('  Returning fallback response');

  return {
    messages: [{
      role: 'assistant',
      content: JSON.stringify({
        result: {
          qualityScore: 0,
          completenessCheck: {},
          executiveSummary: 'Error: No research results found to evaluate. The research phase may not have completed successfully.',
          recommendations: ['Please re-run the research phase'],
          missingTopics: ['All topics'],
          error: 'No research results found',
          debugInfo: {
            receivedContentLength: userContent.length,
            receivedContentPreview: userContent.substring(0, 500)
          }
        }
      }, null, 2)
    }]
  };
}

// Format research results
const findingsSummary = researchResults.map((r, idx) => {
  const taskId = r.taskId || (idx + 1);
  const objective = r.objective || 'No objective';
  const findings = r.findings || r.result || 'No findings';
  const sources = r.sources || [];
  const sourcesStr = sources.length > 0 ? `\nSources: ${sources.join(', ')}` : '';
  return `Task ${taskId}: ${objective}\nFindings: ${findings}${sourcesStr}`;
}).join('\n\n');

console.log('\n📝 Formatted research results (first 500 chars):');
console.log(findingsSummary.substring(0, 500));

// Request evaluation and summary creation from LLM
const evaluationPrompt = `Please create a quality evaluation and executive summary for the following market research.

[Original User Request]
${originalRequest}

[Research Results]
${findingsSummary}

Please return your response in the following format:
EVALUATION_START
{
  "qualityScore": Quality score (0-100),
  "completenessCheck": {
    "Each requested topic": true/false (whether covered)
  },
  "executiveSummary": "Executive summary in English (500-800 characters)",
  "recommendations": ["Improvement recommendation 1", "Improvement recommendation 2"],
  "missingTopics": ["Missing topic 1", "Missing topic 2"]
}
EVALUATION_END

Evaluation criteria:
- completenessCheck: Extract each topic from original user request and determine coverage status
- qualityScore: Comprehensively evaluate completeness, specificity, relevance, and depth (0-100 points)
- executiveSummary: Concise and comprehensive summary useful for business decisions (500-800 characters)
- recommendations: Points requiring further research or improvement
- missingTopics: Topics not covered`;

console.log('\n🤖 Sending evaluation request to LLM...');
console.log('  Prompt length:', evaluationPrompt.length, 'chars');

// Model is passed as a parameter
// Model is now passed as a parameter, so no need to check

const response = await model.invoke([{
  role: 'user',
  content: evaluationPrompt
}]);

console.log('\n✅ LLM response received');

const content = response.content || '';
console.log('  Response length:', content.length, 'chars');
console.log('  First 300 chars:', content.substring(0, 300));

const evaluationMatch = content.match(/EVALUATION_START\s*([\s\S]*?)\s*EVALUATION_END/);

let evaluation;

if (evaluationMatch) {
  try {
    evaluation = JSON.parse(evaluationMatch[1].trim());
    console.log('\n✅ Evaluation result parsed successfully');
    console.log('  Quality Score:', evaluation.qualityScore);
    console.log('  Executive Summary length:', evaluation.executiveSummary?.length || 0, 'chars');
    console.log('  Recommendations:', evaluation.recommendations?.length || 0);
    console.log('  Missing Topics:', evaluation.missingTopics?.length || 0);
  } catch (e) {
    console.error('\n❌ Evaluation result JSON parsing error:', e.message);
    console.log('  Using fallback evaluation');

    // Fallback evaluation
    evaluation = {
      qualityScore: 70,
      completenessCheck: {},
      executiveSummary: content.substring(0, 800),
      recommendations: ['Failed to parse evaluation results'],
      missingTopics: []
    };
  }
} else {
  console.warn('\n⚠️  EVALUATION markers not found');
  console.log('  Using fallback evaluation without markers');

  // Fallback without markers
  evaluation = {
    qualityScore: 70,
    completenessCheck: {},
    executiveSummary: content.substring(0, 800),
    recommendations: [],
    missingTopics: []
  };
}

// Build final result
const result = {
  qualityScore: evaluation.qualityScore,
  completenessCheck: evaluation.completenessCheck,
  executiveSummary: evaluation.executiveSummary,
  recommendations: evaluation.recommendations || [],
  missingTopics: evaluation.missingTopics || [],
  researchResults: researchResults
};

console.log('\n📋 Evaluation report completed');
console.log('  Quality score:', result.qualityScore);
console.log('  Recommendations:', result.recommendations.length);
console.log('  Missing topics:', result.missingTopics.length);
console.log('  Executive summary length:', result.executiveSummary.length, 'chars');

console.log('\n' + '='.repeat(80));
console.log('✅ [QualityEvaluation] Quality evaluation completed');
console.log('='.repeat(80) + '\n');

return {
  messages: [{
    role: 'assistant',
    content: JSON.stringify({ result }, null, 2)
  }]
};
